// displayName is user-controlled profile text.
export function renderPanel(displayName: string): string {
  return '<h1>Welcom</h1><p>' + displayName + '</p>';
}
export function mountPanel(target: HTMLElement, displayName: string): void {
  target.innerHTML = renderPanel(displayName);
}

